//! End-to-end tests for `:cert` and `:verify-cert`.
//!
//! The certificate is generated by one CLI process and checked by a second
//! process that only runs `:load` and `:verify-cert`, so the checker is
//! exercised on the exported JSON, not on the reasoner's in-memory derivation.

use std::fs;
use std::path::{Path, PathBuf};
use std::process::{Command, Output};
use std::sync::atomic::{AtomicU64, Ordering};

use std_deduce_cert::{
    check, ApplicabilityBasis, ApplicabilityReason, ApplicabilityReasonKind, ApplicabilityVerdict,
    Assumption, Binding, CertExpr, Certificate, EnvironmentIdentity, Explicit, FactIdentity,
    FormatVersion, Metadata, Node, ObligationKind, RuleApplicability,
};
use std_deduce_kernel::Expr;
use std_deduce_lang::Library;

const PROVED: i32 = 0;
const GAP: i32 = 1;
const ERROR: i32 = 2;

fn examples_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../examples")
}

fn example(name: &str) -> PathBuf {
    let path = examples_dir().join(name);
    assert!(path.is_file(), "missing example file: {}", path.display());
    path
}

fn load(name: &str) -> Library {
    let path = example(name);
    let src = fs::read_to_string(&path).unwrap_or_else(|e| panic!("read {}: {e}", path.display()));
    let mut lib = Library::new();
    lib.load(name, &src)
        .unwrap_or_else(|e| panic!("load {name}: {e}"));
    lib
}

fn run(commands: Vec<String>) -> Output {
    Command::new(env!("CARGO_BIN_EXE_std-deduce"))
        .args(commands)
        .output()
        .unwrap_or_else(|e| panic!("failed to run the CLI: {e}"))
}

fn session(name: &str, commands: &[String]) -> Output {
    let mut all = vec![format!(":load {}", example(name).display())];
    all.extend_from_slice(commands);
    run(all)
}

fn stdout(output: &Output) -> String {
    String::from_utf8_lossy(&output.stdout).into_owned()
}

/// The record of a rule declared without any scope.
fn unscoped_applicability() -> Box<RuleApplicability> {
    Box::new(RuleApplicability {
        verdict: ApplicabilityVerdict::Unchecked,
        basis: ApplicabilityBasis::default(),
        reason: Explicit::some(ApplicabilityReason::new(
            ApplicabilityReasonKind::RuleHasNoScope,
        )),
    })
}

fn stderr(output: &Output) -> String {
    String::from_utf8_lossy(&output.stderr).into_owned()
}

fn assert_exit(output: &Output, expected: i32) {
    let code = output.status.code();
    assert_eq!(
        code,
        Some(expected),
        "expected exit {expected}, got {code:?}\nstdout:\n{}\nstderr:\n{}",
        stdout(output),
        stderr(output)
    );
}

/// `:load` prints its report before `:cert`, so the certificate is the tail
/// starting at the first `{`.
fn certificate_json(output: &Output) -> Certificate {
    let text = stdout(output);
    let start = text
        .find('{')
        .unwrap_or_else(|| panic!("no certificate JSON in stdout:\n{text}"));
    Certificate::from_json(text[start..].trim_end())
        .unwrap_or_else(|e| panic!("invalid certificate JSON:\n{e}\nstdout:\n{text}"))
}

fn temp_path(tag: &str) -> PathBuf {
    static NEXT: AtomicU64 = AtomicU64::new(0);
    let n = NEXT.fetch_add(1, Ordering::Relaxed);
    std::env::temp_dir().join(format!(
        "std-deduce-cert-{}-{tag}-{n}.json",
        std::process::id()
    ))
}

/// A certificate file removed when the test ends (including on panic).
struct TempFile {
    path: PathBuf,
}

impl TempFile {
    fn new(tag: &str, contents: &str) -> Self {
        let path = temp_path(tag);
        fs::write(&path, contents).unwrap_or_else(|e| panic!("write {}: {e}", path.display()));
        TempFile { path }
    }
}

impl Drop for TempFile {
    fn drop(&mut self) {
        let _ = fs::remove_file(&self.path);
    }
}

/// A temporary directory whose name contains a space, removed on drop.
struct TempSpaceDir {
    path: PathBuf,
}

impl TempSpaceDir {
    fn new(tag: &str) -> Self {
        static NEXT: AtomicU64 = AtomicU64::new(0);
        let n = NEXT.fetch_add(1, Ordering::Relaxed);
        let path =
            std::env::temp_dir().join(format!("std-deduce cert {} {tag} {n}", std::process::id()));
        fs::create_dir_all(&path).unwrap_or_else(|e| panic!("create {}: {e}", path.display()));
        TempSpaceDir { path }
    }

    fn write(&self, name: &str, contents: &str) -> PathBuf {
        let path = self.path.join(name);
        fs::write(&path, contents).unwrap_or_else(|e| panic!("write {}: {e}", path.display()));
        path
    }
}

impl Drop for TempSpaceDir {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.path);
    }
}

fn verify_cert_file(theory: &str, tag: &str, certificate: &Certificate) -> Output {
    let json = certificate.to_json_pretty().unwrap();
    let file = TempFile::new(tag, &json);
    session(theory, &[format!(":verify-cert {}", file.path.display())])
}

fn verify_cert_file_with_goal(
    theory: &str,
    tag: &str,
    certificate: &Certificate,
    goal: &str,
) -> Output {
    let json = certificate.to_json_pretty().unwrap();
    let file = TempFile::new(tag, &json);
    session(
        theory,
        &[format!(":verify-cert {} {goal}", file.path.display())],
    )
}

/// The index and mutable node of the first application of `rule`.
fn rule_node_mut<'a>(certificate: &'a mut Certificate, rule: &str) -> (usize, &'a mut Node) {
    certificate
        .nodes
        .iter_mut()
        .enumerate()
        .find(|(_, node)| {
            matches!(node, Node::RuleApplication { rule: name, .. } if name.as_str() == rule)
        })
        .unwrap_or_else(|| panic!("certificate has no rule application `{rule}`"))
}

/// A proved certificate for the basic defense example, used by mutation tests.
fn defense_certificate() -> Certificate {
    let generated = session(
        "刑法第二十条-基本.std",
        &[":cert 不负刑事责任 乙行为".to_owned()],
    );
    assert_exit(&generated, PROVED);
    certificate_json(&generated)
}

#[test]
fn certificate_round_trips_and_verify_cert_accepts_it() {
    let generated = session(
        "constitution-39.std",
        &[":cert 不受侵犯 张三 甲宅".to_owned()],
    );
    assert_exit(&generated, PROVED);

    let certificate = certificate_json(&generated);
    assert!(certificate.root.is_some(), "the goal is proved");
    assert!(
        matches!(certificate.environment, EnvironmentIdentity::Recorded(_)),
        ":cert must stamp a recorded environment identity"
    );

    let pretty = certificate.to_json_pretty().unwrap();
    let reparsed = Certificate::from_json(&pretty).expect("the exported JSON round-trips");
    assert_eq!(reparsed, certificate);

    let lib = load("constitution-39.std");
    let report = check(&lib.env, &certificate).expect("the generated certificate checks");
    assert!(report.root_proved);
    assert!(!report.requires_human, "no obligation is left open");
    assert_eq!(report.nodes_checked, certificate.nodes.len());

    // A fresh process sees only the loaded theory and the file, and both
    // layers report separately.
    let checked = verify_cert_file("constitution-39.std", "valid", &certificate);
    assert_exit(&checked, PROVED);
    let out = stdout(&checked);
    for label in [
        "环境校验：通过",
        "逻辑校验：通过",
        "内核证明：通过",
        "侧条件：",
        "需人判断：否",
    ] {
        assert!(out.contains(label), "missing {label:?}:\n{out}");
    }
    assert!(out.contains("根已证明"), "{out}");
}

#[test]
fn gap_certificate_is_valid_but_reports_root_not_proved() {
    let generated = session(
        "刑法第二十条-基本.std",
        &[":cert 应当负刑事责任 乙行为".to_owned()],
    );
    assert_exit(&generated, GAP);

    let certificate = certificate_json(&generated);
    let root = certificate.root.expect("a gap certificate has a root");
    assert!(
        matches!(certificate.nodes[root], Node::Gap { .. }),
        "an unreachable goal must be exported as a gap"
    );

    assert!(
        certificate.open_obligations.iter().any(|obligation| {
            obligation.kind == ObligationKind::MissingPremise
                && obligation.nodes == vec![root]
                && obligation.description.contains("应当负刑事责任 乙行为")
        }),
        "a gap must become a MissingPremise obligation for its node: {:?}",
        certificate.open_obligations
    );

    let lib = load("刑法第二十条-基本.std");
    let report = check(&lib.env, &certificate).expect("a gap certificate is well-formed");
    assert!(!report.root_proved);
    assert!(report.requires_human, "the gap obligation needs a human");

    let checked = verify_cert_file("刑法第二十条-基本.std", "gap", &certificate);
    assert_exit(&checked, GAP);
    let out = stdout(&checked);
    assert!(out.contains("环境校验：通过"), "{out}");
    assert!(out.contains("逻辑校验：通过"), "{out}");
    assert!(out.contains("内核证明：通过"), "{out}");
    assert!(out.contains("根未被证明"), "{out}");
    assert!(out.contains("需人判断：是"), "{out}");
    assert!(out.contains("缺少前提 1 项"), "{out}");
}

#[test]
fn unresolved_conflicts_become_open_obligations() {
    let generated = session("冲突-互补谓词.std", &[":cert 批准 甲".to_owned()]);
    assert_exit(&generated, GAP);
    let certificate = certificate_json(&generated);

    assert!(
        certificate.open_obligations.iter().any(|obligation| {
            obligation.kind == ObligationKind::UnresolvedConflict
                && obligation.description.contains("批准 甲")
                && obligation.description.contains("不批准 甲")
        }),
        "an unresolved conflict must become an UnresolvedConflict obligation: {:?}",
        certificate.open_obligations
    );
    assert!(
        certificate.open_obligations.iter().any(|obligation| {
            obligation.kind == ObligationKind::MissingPremise
                && obligation.description.contains("目标处于冲突中")
        }),
        "the conflicting goal is exported as a gap as well: {:?}",
        certificate.open_obligations
    );

    let lib = load("冲突-互补谓词.std");
    let report = check(&lib.env, &certificate).expect("the conflict certificate is well-formed");
    assert!(!report.root_proved);
    assert!(report.requires_human);

    let checked = verify_cert_file("冲突-互补谓词.std", "unresolved", &certificate);
    assert_exit(&checked, GAP);
    let out = stdout(&checked);
    assert!(out.contains("环境校验：通过"), "{out}");
    assert!(out.contains("未决冲突 1 项"), "{out}");
    assert!(out.contains("冲突未决 1 项"), "{out}");
    assert!(out.contains("需人判断：是"), "{out}");
}

#[test]
fn a_defeated_loser_is_exported_as_rejected_not_unresolved() {
    let generated = session(
        "法律位阶-河南种子案-裁决.std",
        &[":cert 应适用 河南省农作物种子管理条例 汝阳种子公司案".to_owned()],
    );
    assert_exit(&generated, GAP);
    let certificate = certificate_json(&generated);
    assert!(
        certificate.open_obligations.iter().any(|obligation| {
            obligation.kind == ObligationKind::MissingPremise
                && obligation.description.contains("目标已被否决")
                && obligation.description.contains("依据见冲突记录")
        }),
        "a defeated loser must not be exported as an unresolved conflict: {:?}",
        certificate.open_obligations
    );
    assert!(
        !certificate.open_obligations.iter().any(|obligation| {
            obligation.kind == ObligationKind::MissingPremise
                && obligation.description.contains("需要人工裁决")
        }),
        "a decided conflict does not need an unresolved-conflict note: {:?}",
        certificate.open_obligations
    );
}

#[test]
fn tampered_conclusion_or_binding_is_rejected() {
    let generated = session(
        "constitution-39.std",
        &[":cert 不受侵犯 张三 甲宅".to_owned()],
    );
    let certificate = certificate_json(&generated);

    let mut bad_conclusion = certificate.clone();
    let conclusion = bad_conclusion
        .nodes
        .iter_mut()
        .find_map(|node| match node {
            Node::RuleApplication { conclusion, .. } => Some(conclusion),
            _ => None,
        })
        .expect("the certificate has a rule application");
    let wrong = Expr::apps(
        Expr::constant("非法搜查"),
        [Expr::constant("张三"), Expr::constant("甲宅")],
    );
    *conclusion = CertExpr::try_from(&wrong).unwrap();
    let checked = verify_cert_file("constitution-39.std", "bad-conclusion", &bad_conclusion);
    assert_exit(&checked, ERROR);
    let out = stdout(&checked);
    assert!(out.contains("环境校验：通过"), "{out}");
    assert!(out.contains("逻辑校验：失败"), "{out}");
    assert!(out.contains("内核证明：未运行"), "{out}");
    let err = stderr(&checked);
    assert!(err.contains("证书校验失败"), "{err}");
    assert!(err.contains("节点"), "{err}");

    let mut bad_binding = certificate.clone();
    let binding = bad_binding
        .nodes
        .iter_mut()
        .find_map(|node| match node {
            Node::RuleApplication { bindings, .. } => bindings.first_mut(),
            _ => None,
        })
        .expect("the rule application has a binding");
    binding.value = CertExpr::Const {
        name: "甲宅".to_owned(),
    };
    let checked = verify_cert_file("constitution-39.std", "bad-binding", &bad_binding);
    assert_exit(&checked, ERROR);
    let out = stdout(&checked);
    assert!(out.contains("逻辑校验：失败"), "{out}");
    assert!(out.contains("内核证明：未运行"), "{out}");
    let err = stderr(&checked);
    assert!(err.contains("证书校验失败"), "{err}");
    assert!(err.contains("节点"), "{err}");

    // The binding below is closed and the premise normalizes to the cited
    // proposition, so the logical layer accepts the step. The kernel still
    // checks the parameter's type and rejects it at the rule node. The process
    // must exit 2 and name the node, never report a valid certificate.
    let theory = TempFile::new(
        "kernel-node-theory",
        "sort 人\nsort 物\nobj 张三 : 人\nobj 甲 : 物\naxiom 真 : Prop\n  source text \"测试\" locator \"夹具\"\ndef 恒 : 人 → Prop := λ (u : 人) := 真\nrule 恒真 :\n  params x : 人\n  premise 恒 x\n  conclude 真\n  source text \"测试\" locator \"夹具\"\n",
    );
    let truth = CertExpr::Const {
        name: "真".to_owned(),
    };
    let kernel_failure = Certificate {
        format_version: FormatVersion::CURRENT,
        environment: EnvironmentIdentity::none(),
        assumptions: vec![Assumption {
            proposition: truth.clone(),
            identity: FactIdentity::UserAsserted,
            sources: Vec::new(),
            label: None,
            occurred_at: Explicit::none(),
            occurred_in: Explicit::none(),
        }],
        interpretations: Vec::new(),
        nodes: vec![
            Node::Assumption { assumption: 0 },
            Node::RuleApplication {
                rule: "恒真".to_owned(),
                conclusion: truth,
                premises: vec![0],
                bindings: vec![Binding {
                    parameter: "x".to_owned(),
                    value: CertExpr::Const {
                        name: "甲".to_owned(),
                    },
                }],
                sources: Vec::new(),
                applicability: unscoped_applicability(),
            },
        ],
        root: Some(1),
        alternatives: Vec::new(),
        conflicts: Vec::new(),
        open_obligations: Vec::new(),
        metadata: Metadata::default(),
    };
    let cert_file = TempFile::new(
        "kernel-node-failure",
        &kernel_failure.to_json_pretty().unwrap(),
    );
    let checked = run(vec![
        format!(":load {}", theory.path.display()),
        format!(":verify-cert {}", cert_file.path.display()),
    ]);
    assert_exit(&checked, ERROR);
    let out = stdout(&checked);
    assert!(out.contains("逻辑校验：通过"), "{out}");
    assert!(out.contains("内核证明：失败"), "{out}");
    let err = stderr(&checked);
    assert!(err.contains("证书校验失败（内核层）"), "{err}");
    assert!(err.contains("节点 1"), "{err}");
    assert!(err.contains("期望 人，实际 物"), "{err}");
}

#[test]
fn verify_cert_rejects_missing_and_malformed_files() {
    let missing = temp_path("missing");
    let checked = session(
        "constitution-39.std",
        &[format!(":verify-cert {}", missing.display())],
    );
    assert_exit(&checked, ERROR);
    let out = stdout(&checked);
    assert!(out.contains("环境校验：未运行"), "{out}");
    let err = stderr(&checked);
    assert!(err.contains("读取证书"), "{err}");
    assert!(err.contains("失败"), "{err}");

    let malformed = TempFile::new("malformed", "这不是证书 JSON");
    let checked = session(
        "constitution-39.std",
        &[format!(":verify-cert {}", malformed.path.display())],
    );
    assert_exit(&checked, ERROR);
    let out = stdout(&checked);
    assert!(out.contains("环境校验：未运行"), "{out}");
    let err = stderr(&checked);
    assert!(err.contains("不是有效的证书 JSON"), "{err}");
}

#[test]
fn verify_cert_escapes_a_read_failure_path_onto_one_line() {
    let missing = temp_path("坏\u{001B}\u{202E}\n路径");
    let checked = session(
        "constitution-39.std",
        &[format!(":verify-cert \"{}\"", missing.display())],
    );
    assert_exit(&checked, ERROR);
    let err = stderr(&checked);
    assert_eq!(
        err.lines().count(),
        1,
        "exactly one diagnostic line:\n{err:?}"
    );
    assert!(err.contains("读取证书"), "{err:?}");
    assert!(err.contains("\\u{001B}"), "ESC must be escaped:\n{err:?}");
    assert!(
        err.contains("\\u{202E}"),
        "U+202E must be escaped:\n{err:?}"
    );
    assert!(err.contains("\\n"), "the newline must be escaped:\n{err:?}");
    assert!(!err.contains('\u{001B}'), "{err:?}");
    assert!(!err.contains('\u{202E}'), "{err:?}");
}

#[test]
fn verify_cert_requires_a_loaded_environment() {
    let certificate = Certificate::from_json(
        r#"{"format_version": 9, "environment": {"profile": null, "packs": [],
            "corpora": [], "as_of": null, "jurisdiction": null},
            "interpretations": [], "nodes": [], "root": null, "alternatives": []}"#,
    )
    .expect("a minimal valid certificate");
    let json = certificate.to_json_pretty().unwrap();
    let file = TempFile::new("no-env", &json);

    let checked = run(vec![format!(":verify-cert {}", file.path.display())]);
    assert_exit(&checked, ERROR);
    let out = stdout(&checked);
    assert!(out.contains("环境校验：未运行"), "{out}");
    assert!(out.contains("逻辑校验：未运行"), "{out}");
    assert!(out.contains("内核证明：未运行"), "{out}");
    assert!(out.contains("侧条件：未评估"), "{out}");
    assert!(out.contains("需人判断：未评估"), "{out}");
    let err = stderr(&checked);
    assert!(err.contains("尚未加载理论"), "{err}");
}

#[test]
fn deleting_a_rule_premise_is_rejected() {
    let mut certificate = defense_certificate();
    let (node, rule) = rule_node_mut(&mut certificate, "认定正当防卫");
    let Node::RuleApplication { premises, .. } = rule else {
        unreachable!("rule_node_mut returns a rule application");
    };
    premises.remove(2);

    let checked = verify_cert_file("刑法第二十条-基本.std", "missing-premise", &certificate);
    assert_exit(&checked, ERROR);
    let out = stdout(&checked);
    assert!(out.contains("逻辑校验：失败"), "{out}");
    assert!(out.contains("内核证明：未运行"), "{out}");
    let err = stderr(&checked);
    assert!(err.contains(&format!("节点 {node}")), "{err}");
    assert!(err.contains("认定正当防卫"), "{err}");
    assert!(err.contains("前提"), "{err}");
}

#[test]
fn changing_a_rule_binding_to_a_wrong_individual_is_rejected() {
    let mut certificate = defense_certificate();
    let (node, rule) = rule_node_mut(&mut certificate, "认定正当防卫");
    let Node::RuleApplication { bindings, .. } = rule else {
        unreachable!("rule_node_mut returns a rule application");
    };
    let binding = bindings
        .iter_mut()
        .find(|binding| binding.parameter == "x")
        .expect("认定正当防卫 binds x");
    binding.value = CertExpr::Const {
        name: "张三".to_owned(),
    };

    let checked = verify_cert_file("刑法第二十条-基本.std", "wrong-binding", &certificate);
    assert_exit(&checked, ERROR);
    let out = stdout(&checked);
    assert!(out.contains("逻辑校验：失败"), "{out}");
    let err = stderr(&checked);
    assert!(err.contains(&format!("节点 {node}")), "{err}");
    assert!(err.contains("认定正当防卫"), "{err}");
    assert!(err.contains("张三"), "{err}");
    assert!(err.contains("李四"), "{err}");
}

#[test]
fn changing_a_rule_conclusion_is_rejected() {
    let mut certificate = defense_certificate();
    let (node, rule) = rule_node_mut(&mut certificate, "正当防卫不负刑责");
    let Node::RuleApplication { conclusion, .. } = rule else {
        unreachable!("rule_node_mut returns a rule application");
    };
    let wrong = Expr::apps(Expr::constant("正当防卫"), [Expr::constant("乙行为")]);
    *conclusion = CertExpr::try_from(&wrong).unwrap();

    let checked = verify_cert_file("刑法第二十条-基本.std", "wrong-conclusion", &certificate);
    assert_exit(&checked, ERROR);
    let out = stdout(&checked);
    assert!(out.contains("逻辑校验：失败"), "{out}");
    let err = stderr(&checked);
    assert!(err.contains(&format!("节点 {node}")), "{err}");
    assert!(err.contains("实例结论"), "{err}");
    assert!(err.contains("不负刑事责任 乙行为"), "{err}");
    assert!(err.contains("正当防卫 乙行为"), "{err}");
}

#[test]
fn reusing_a_wrong_premise_node_is_rejected() {
    let mut certificate = defense_certificate();
    // The unrelated fact node is found by its proposition: node order is
    // deterministic but the assumptions are ordered by declaration name.
    let unrelated = certificate
        .nodes
        .iter()
        .position(|node| {
            matches!(
                node,
                Node::Assumption { assumption }
                    if certificate.assumptions[*assumption].proposition
                        == CertExpr::try_from(&Expr::apps(
                            Expr::constant("不法"),
                            [Expr::constant("甲侵害")]
                        ))
                        .unwrap()
            )
        })
        .expect("the certificate contains the 不法 fact");
    let (node, rule) = rule_node_mut(&mut certificate, "正当防卫不负刑责");
    let Node::RuleApplication { premises, .. } = rule else {
        unreachable!("rule_node_mut returns a rule application");
    };
    premises[0] = unrelated;

    let checked = verify_cert_file("刑法第二十条-基本.std", "wrong-premise-node", &certificate);
    assert_exit(&checked, ERROR);
    let out = stdout(&checked);
    assert!(out.contains("逻辑校验：失败"), "{out}");
    let err = stderr(&checked);
    assert!(err.contains(&format!("节点 {node}")), "{err}");
    assert!(err.contains("正当防卫不负刑责"), "{err}");
    assert!(err.contains(&format!("引用的节点 {unrelated}")), "{err}");
    assert!(err.contains("正当防卫 乙行为"), "{err}");
    assert!(err.contains("不法 甲侵害"), "{err}");
}

#[test]
fn adding_a_satisfied_unless_blocker_is_rejected() {
    let mut certificate = defense_certificate();
    let root = certificate.root.expect("the defense certificate is proved");
    let blocker = Expr::apps(Expr::constant("防卫过当"), [Expr::constant("乙行为")]);
    // The assumption is not cited by any node; `cert::check` still puts every
    // listed assumption in scope, so it must retract the `unless` step.
    certificate.assumptions.push(Assumption {
        proposition: CertExpr::try_from(&blocker).unwrap(),
        identity: FactIdentity::UserAsserted,
        sources: Vec::new(),
        label: Some("变异：追加已成立的阻断条件".to_owned()),
        occurred_at: Explicit::none(),
        occurred_in: Explicit::none(),
    });

    let checked = verify_cert_file("刑法第二十条-基本.std", "satisfied-blocker", &certificate);
    assert_exit(&checked, ERROR);
    let out = stdout(&checked);
    assert!(out.contains("逻辑校验：失败"), "{out}");
    let err = stderr(&checked);
    assert!(err.contains(&format!("节点 {root}")), "{err}");
    assert!(err.contains("正当防卫不负刑责"), "{err}");
    assert!(err.contains("阻断条件"), "{err}");
    assert!(err.contains("已成立"), "{err}");
    assert!(err.contains("防卫过当 乙行为"), "{err}");
}

#[test]
fn swapped_root_stays_valid_but_fails_the_goal_binding() {
    let mut certificate = defense_certificate();
    let original_root = certificate.root.expect("the defense certificate is proved");
    assert!(matches!(
        certificate.nodes[original_root],
        Node::RuleApplication { .. }
    ));
    assert!(matches!(certificate.nodes[0], Node::Assumption { .. }));
    certificate.root = Some(0);

    // The certificate is still legal by itself: its root is an assumption.
    let checked = verify_cert_file("刑法第二十条-基本.std", "swapped-root", &certificate);
    assert_exit(&checked, PROVED);
    let out = stdout(&checked);
    assert!(out.contains("环境校验：通过"), "{out}");
    assert!(out.contains("逻辑校验：通过"), "{out}");
    assert!(out.contains("根为假设"), "{out}");
    assert!(!out.contains("目标绑定"), "{out}");

    // But it no longer proves the goal it was generated for.
    let checked = verify_cert_file_with_goal(
        "刑法第二十条-基本.std",
        "swapped-root-goal",
        &certificate,
        "不负刑事责任 乙行为",
    );
    assert_exit(&checked, ERROR);
    let out = stdout(&checked);
    assert!(out.contains("逻辑校验：通过"), "{out}");
    assert!(out.contains("内核证明：通过"), "{out}");
    assert!(out.contains("目标绑定：失败"), "{out}");
    assert!(!out.contains("目标绑定：通过"), "{out}");
    let err = stderr(&checked);
    assert!(err.contains("目标绑定失败"), "{err}");
    // Node 0 is the first assumption in declaration-name order.
    assert!(err.contains("制止 乙行为 甲侵害"), "{err}");
    assert!(err.contains("不负刑事责任 乙行为"), "{err}");
    assert!(err.contains("不等价"), "{err}");
}

#[test]
fn matching_goal_keeps_a_valid_certificate_passing() {
    let certificate = defense_certificate();

    let checked = verify_cert_file("刑法第二十条-基本.std", "goal-control", &certificate);
    assert_exit(&checked, PROVED);
    assert!(!stdout(&checked).contains("目标绑定"));

    let checked = verify_cert_file_with_goal(
        "刑法第二十条-基本.std",
        "goal-control-with-goal",
        &certificate,
        "不负刑事责任 乙行为",
    );
    assert_exit(&checked, PROVED);
    let out = stdout(&checked);
    for label in [
        "环境校验：通过",
        "逻辑校验：通过",
        "内核证明：通过",
        "侧条件：",
        "需人判断：否",
        "目标绑定：通过（根命题与目标在内核下等价）",
    ] {
        assert!(out.contains(label), "missing {label:?}:\n{out}");
    }
}

#[test]
fn a_gap_root_cannot_satisfy_a_goal_binding() {
    let generated = session(
        "刑法第二十条-基本.std",
        &[":cert 应当负刑事责任 乙行为".to_owned()],
    );
    assert_exit(&generated, GAP);
    let certificate = certificate_json(&generated);

    let checked = verify_cert_file_with_goal(
        "刑法第二十条-基本.std",
        "gap-goal",
        &certificate,
        "应当负刑事责任 乙行为",
    );
    assert_exit(&checked, ERROR);
    let out = stdout(&checked);
    assert!(out.contains("逻辑校验：通过"), "{out}");
    assert!(
        out.contains("目标绑定：失败（根为缺口，不证明任何命题）"),
        "{out}"
    );
    let err = stderr(&checked);
    assert!(err.contains("目标绑定失败"), "{err}");
}

#[test]
fn goal_binding_uses_kernel_conversion_not_printed_text() {
    let theory = TempFile::new(
        "goal-conversion-theory",
        "sort 人\n\
         obj 张三 : 人\n\
         pred 好人 : 人 → Prop\n\
         def 善 : 人 → Prop := λ (x : 人) := 好人 x\n\
         axiom 张三是好人 : 好人 张三\n\
           source text \"测试\" locator \"夹具\"\n",
    );
    let generated = run(vec![
        format!(":load {}", theory.path.display()),
        ":cert 好人 张三".to_owned(),
    ]);
    assert_exit(&generated, PROVED);
    let certificate = certificate_json(&generated);
    let root = certificate.root.expect("the axiom is the root");
    assert!(matches!(certificate.nodes[root], Node::Assumption { .. }));

    let file = TempFile::new(
        "goal-conversion-cert",
        &certificate.to_json_pretty().unwrap(),
    );
    let checked = run(vec![
        format!(":load {}", theory.path.display()),
        format!(":verify-cert {} 善 张三", file.path.display()),
    ]);
    assert_exit(&checked, PROVED);
    let out = stdout(&checked);
    assert!(out.contains("目标绑定：通过"), "{out}");
}

/// The unquoted form must keep working when the certificate path contains
/// spaces: the whole argument names the existing file, so no goal is split off.
#[test]
fn verify_cert_accepts_an_unquoted_path_with_spaces_without_a_goal() {
    let generated = session(
        "constitution-39.std",
        &[":cert 不受侵犯 张三 甲宅".to_owned()],
    );
    assert_exit(&generated, PROVED);
    let certificate = certificate_json(&generated);

    let dir = TempSpaceDir::new("unquoted");
    let file = dir.write("cert one.json", &certificate.to_json_pretty().unwrap());
    let checked = session(
        "constitution-39.std",
        &[format!(":verify-cert {}", file.display())],
    );
    assert_exit(&checked, PROVED);
    let out = stdout(&checked);
    assert!(out.contains("逻辑校验：通过"), "{out}");
    assert!(!out.contains("目标绑定："), "{out}");
}

/// A quoted path may contain spaces and still be followed by a goal.
#[test]
fn verify_cert_accepts_a_quoted_path_with_spaces_and_a_goal() {
    let generated = session(
        "constitution-39.std",
        &[":cert 不受侵犯 张三 甲宅".to_owned()],
    );
    assert_exit(&generated, PROVED);
    let certificate = certificate_json(&generated);

    let dir = TempSpaceDir::new("quoted");
    let file = dir.write("cert two.json", &certificate.to_json_pretty().unwrap());
    let checked = session(
        "constitution-39.std",
        &[format!(
            ":verify-cert \"{}\" 不受侵犯 张三 甲宅",
            file.display()
        )],
    );
    assert_exit(&checked, PROVED);
    let out = stdout(&checked);
    assert!(out.contains("目标绑定：通过"), "{out}");
}

/// A certificate without a root cannot be bound to a goal.
#[test]
fn a_missing_root_cannot_satisfy_a_goal_binding() {
    let mut certificate = defense_certificate();
    certificate.root = None;
    let file = TempFile::new("goal-missing-root", &certificate.to_json_pretty().unwrap());
    let checked = session(
        "刑法第二十条-基本.std",
        &[format!(
            ":verify-cert {} 不负刑事责任 乙行为",
            file.path.display()
        )],
    );
    assert_exit(&checked, ERROR);
    let out = stdout(&checked);
    assert!(out.contains("目标绑定：失败（证书没有根节点）"), "{out}");
}

/// A goal that cannot be parsed is a binding failure, not a silent pass.
#[test]
fn an_unparseable_goal_fails_the_binding() {
    let certificate = defense_certificate();
    let file = TempFile::new("goal-unparseable", &certificate.to_json_pretty().unwrap());
    let checked = session(
        "刑法第二十条-基本.std",
        &[format!(
            ":verify-cert {} 不存在的谓词 某人",
            file.path.display()
        )],
    );
    assert_exit(&checked, ERROR);
    let out = stdout(&checked);
    assert!(out.contains("目标绑定：失败（目标无法解析"), "{out}");
}

/// The old `:check` name is gone, not an alias: it must point at
/// `:verify-cert` and exit `2` instead of checking anything.
#[test]
fn the_removed_check_command_reports_the_rename() {
    for command in [":check".to_owned(), ":check missing.json".to_owned()] {
        let checked = run(vec![command.clone()]);
        assert_exit(&checked, ERROR);
        let err = stderr(&checked);
        assert!(err.contains(":check"), "{command}: {err}");
        assert!(err.contains(":verify-cert"), "{command}: {err}");
        assert!(err.contains("已改名"), "{command}: {err}");
    }
}
